	public static Stroke getReferenceStroke(String key) {
		if(sampleMap==null) initReferenceSamples();
		Stroke  s = sampleMap.get(key);
		return s;
	}
	
	public static int getSampleCount() {
		if(keys==null) initReferenceSamples();
		return keys.size();
	}
	
	public static String[] getTekens() {
		if(keys==null) initReferenceSamples();
		return keys.toArray(new String[10]);
	}
	
	
